$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'コミットはこのサーバーでチェックアウトされている Git リビジョンを示します。ローカルでのファイル編集は含まれません。そのコミットを直接指す Git タグがある場合は表示されます。';
