$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = '配信中に配信先との接続が切断されました。一時的なネットワークの問題の可能性があります。FFMPEG が再接続を試みます。';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'YouTube への接続が中断されました。アップロードは一時停止されており、再開できます。';
