$t['The connection was renewed.'] = '接続が更新されました。';
$t['The connection window was closed before the authorization finished. No account was connected.'] = '認証が完了する前に接続ウィンドウが閉じられました。アカウントは連携されていません。';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = '変換済みファイルは保持されています。転送を再試行するにはサイト管理者に連絡してください。動画を再度アップロードする必要はありません。';
$t['The converted video could not be sent back to this site.'] = '変換された動画をこのサイトに送り返せませんでした。';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = '選択したカードの顧客です。検索、並べ替え、メールアドレスのコピー、またはすべてをスプレッドシートにエクスポートできます。';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'このサイトの1日あたりのYouTubeアップロード上限に達しました。太平洋時間の午前0時以降に再びアップロードできるようになります。しばらくしてからもう一度お試しください。';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'データベースのバージョンは、データベースの移行が適用されたときにのみ変わります。リリースタグやコミットと一致する必要はありません。';
$t['The default'] = 'デフォルト';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = '送信先のRTMPサーバーが接続を拒否しました。ストリームURLを確認し、サーバーがオンラインであることを確認してください。';
$t['The destination server requires authentication. Check the stream key.'] = '送信先サーバーで認証が必要です。ストリームキーを確認してください。';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = '送信先サーバーが403を返しました。ストリームキーが無効か期限切れの可能性があります。';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = '送信先の動画が削除されたか、このアカウントでは編集できません。サイト上で動画とアカウントのアクセス権を確認してください。';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
