$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'エンコーダーから動画がキューに追加されたことの確認がありませんでした。もう一度お試しください。';
$t['The encoder is running out of disk space'] = 'エンコーダーのディスク容量が不足しています';
$t['The encoder reported an unexpected error.'] = 'エンコーダーで予期しないエラーが発生しました。';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'エンコード処理が予期せず停止し、自動再試行も失敗しました。';
