$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'このギフトコードはキャンセルされました。心当たりがない場合は、サポートチームまでお問い合わせください。';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'このギフトコードは現在無効です。後ほど再度ご確認いただくか、サポートまでお問い合わせください。';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = '上記の情報は当社の公式記録と一致しており、この証明書が本物であることを証明します。';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = '入力ストリームに無効なデータが含まれています。ソースのHLSがまだ準備できていないか、ストリームが中断された可能性があります。';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'インストール済みのPHPパッケージには両方の修正が含まれていますが、このWebプロセスは更新前に読み込まれたものを実行し続けています。ApacheまたはPHP-FPMを再起動してください。';
