$t['The request to the social network failed. Please try again later.'] = 'ソーシャルネットワークへのリクエストに失敗しました。しばらくしてからもう一度お試しください。';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'リストリーマーサーバーが送信先に到達できません。ネットワーク接続を確認してください。';
