$t['The selected camera or microphone is not available. Please choose another device.'] = '選択したカメラまたはマイクは利用できません。別のデバイスを選択してください。';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = '選択した位置は実際のページ上で強調表示されます。モバイルプレビューで変わるのは広告の位置のみで、ページのその他の部分はお使いのブラウザのデバイスで表示されます。';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = '選択した位置は、サイトの実際のページ上に枠線で示され、下で選択する位置に合わせて変わります。モバイルプレビューで変わるのは広告の位置のみで、ページのその他の部分はお使いのブラウザのデバイスに従って表示されます。';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'データベースの問題により、現在サイトはオフラインです。できるだけ早く問題を解決するよう対応しております。';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'サーバーのディスクがいっぱいのため、サイトは一時的に利用できません。現在対応中ですので、まもなく復旧します。';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'サーバーのディスク容量が上限に近づいているため、サイトはメンテナンス中です。現在対応中ですので、まもなく復旧します。';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'サイトがアクセスを拒否しました。エンコーダーアカウントのアクセスを更新し、アップロード権限を確認してください。';
$t['The site will display only a login form to un authenticated users'] = 'ログインを必須とします。初期画面ではログイン画面を表示します';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'ソースストリームが終了しました。意図的にライブを停止した場合は正常です。';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = '分割が有効です:現在、デスクトップの訪問者にはこのバナーは表示されず、左右の半分が表示されます。';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'ストリームのタイムスタンプが不連続です。送信先のプラットフォームでバッファリングや再生の問題が発生する可能性があります。';
